import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class LittleCLoves3II {
    private static long answer(long n, long m) {
        if (n > m) {
            n = n + m;
            m = n - m;
            n = n - m;
        }

        if (n == 1) {
            return m / 6 * 6 + Math.max(m % 6 - 3, 0) * 2;
        }

        if (n == 2) {
            if (m == 2) return 0;
            if (m == 3) return 4;
            if (m == 7) return 12;
            return 2L * m;
        }

        return (n * m) & ~1L;
    }

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(new BufferedReader(new InputStreamReader(System.in)));
        PrintWriter out = new PrintWriter(System.out);
        out.println(answer(sc.nextInt(), sc.nextInt()));
        out.close();
    }

    static class FastScanner {
        BufferedReader in;
        StringTokenizer st;

        public FastScanner(BufferedReader in) {
            this.in = in;
        }

        public String nextToken() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(in.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(nextToken());
        }
    }
}
